def migrate_token(apps, schema_editor):
    """Move each provider's token into a Secret object"""
    db_alias = schema_editor.connection.alias
    SCIMProvider = apps.get_model("authentik_providers_scim", "SCIMProvider")
    Secret = apps.get_model("authentik_secrets", "Secret")
    names = set(Secret.objects.using(db_alias).values_list("name", flat=True))
    for provider in SCIMProvider.objects.using(db_alias).exclude(_token=""):
        base = f"{provider.name} SCIM token"
        name, idx = base, 2
        while name in names:
            name = f"{base} ({idx})"
            idx += 1
        names.add(name)
        provider.secret = Secret.objects.using(db_alias).create(
            name=name,
            value=provider._token,
            type="multiline" if "\n" in provider._token else "text",
        )
        provider.save(update_fields=["secret"])


